import "dart:io"; void main() { var files = Directory("lib").listSync(recursive: true).where((e) => e.path.endsWith(".dart")); for (var f in files) { var file = File(f.path); var content = file.readAsStringSync(); var newContent = content.replaceAll("const SnackBar", "SnackBar").replaceAll(RegExp(r"const InputDecoration\(\s*labelText: AppLocalizations"), "InputDecoration(\nlabelText: AppLocalizations"); file.writeAsStringSync(newContent); } }
